class Book {
  long author_id_;
  std::optional<Author> author_;
  std::once_flag loaded_;
 public:
  const Author& author() {
    std::call_once(loaded_, [this] { author_ = author_gateway(author_id_); });
    return *author_;              // loaded exactly once
  }
};

class AuthorProxy : public Author {
  std::once_flag once_;
  std::unique_ptr<Author> real_;
 public:
  std::string name() const override {
    std::call_once(once_, [this] { real_ = load_author(author_id_); });
    return real_->name();
  }
};

const Rates& rates() {
  static const Rates r = load_rates();   // thread-safe magic static (C++11)
  return r;
}

